"""User-approved, edited migration of twelve public Notion articles. No runtime seeding."""
from html import escape
from urllib.parse import quote

BATCH = 'notion-free-20261005'
SPACE = '081faceb-9338-4366-9246-8be9793cbd22'

def p(text): return '<p>'+escape(text, quote=False)+'</p>'
def h(text): return '<h2>'+escape(text, quote=False)+'</h2>'
def code(text): return '<pre><code>'+escape(text, quote=False)+'</code></pre>'
def bullets(*items): return '<ul>'+''.join('<li>'+escape(t, quote=False)+'</li>' for t in items)+'</ul>'
def link(url, label): return '<p><a href="'+escape(url, quote=True)+'" rel="noopener noreferrer">'+escape(label, quote=False)+'</a></p>'

def article(key, title, description, source_id, source_path, attachment, filename, tags, courses, *blocks):
    source = 'https://vkopytov.notion.site/'+source_path
    # Exact attachment URLs observed on the user's public pages, not guessed assets.
    image = 'https://vkopytov.notion.site/image/'+quote('attachment:'+attachment+':'+filename, safe='()')+'?table=block&id='+source_id+'&spaceId='+SPACE+'&width=2000&userId=&cache=v2&imgBuildSrc=requestProxiedImageUrl'
    return dict(key=key,title=title,description=description,source=source,cover_source=image,tags=tags,courses=courses,
                html=''.join(blocks)+'<hr>'+p('Из архива «ChatGPT для учителя». Примеры и пояснения актуализированы 5 октября 2026 года.')+link(source,'Исходная публикация в Notion'))

